'use strict';
// Dark academia · serif headings · ink/paper/brass · motion depicts recorded workflow.
window.WorkbenchUI = (() => {
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const $ = s => document.querySelector(s);
  const fmt = x => Number.isFinite(x) ? new Intl.NumberFormat('zh-TW', {maximumFractionDigits:2}).format(x) : '未錄';
  const labels = ['核對原料','實錄稱量','設定工序','操作演示'];
  const stages = ['select','quantity','process','structure'];
  const stationLabels={materials:'備料區',weighing:'稱量台',processing:'炮製／規格',assembly:'調劑台',decoction:'製備台',filtration:'濾取台',record:'記錄台'};
  const operationStatuses={empty:'尚未選材',invalid:'請核對',record_missing:'待錄',record_partial:'部分已錄',record_complete:'欄位已錄',not_applicable:'此製法未用'};
  const methods={unrecorded:'製備方式未確認',decoction:'煎劑研究',powder:'散劑製法核對',pill:'丸劑製法核對',other:'其他製法核對'};
  let selectedStation='materials',timelineKey='',liveFlow=null,previewSeeking=false;
  const statuses = {empty:'尚未選材',invalid:'請核對',partial:'有資料待補',ready:'記錄可用'};
  let ctx, step = 0, scene = null, generation = 0, selectedId = null, progress = 0, playing = false;
  let modulePromise;
  const H = id => window.HERB_DATA.herbs.find(h => h.id === id);
  const profile = id => window.PROCESSING_DATA.profiles.find(p => p.id === id);
  function snapshot() {return WorkstationModel.snapshot(ctx.selection(),ctx.processing(),{basis:ctx.basis(),massContext:ctx.massContext(),name:ctx.name(),origin:ctx.origin(),preparation:ctx.preparation(),processPlan:ctx.processPlan()});}
  function sceneSnapshot(flow) {
    return {rows:flow.scene.nodes.map(n=>({id:n.id,name:H(n.id)?.name||n.name,grams:n.grams,ratio:n.ratio,role:n.role,natureGroup:HerbModel.natureGroup(n.attributes?.nature),processingLabel:n.processingLabel,preparationInstruction:ctx.selection().find(r=>r.id===n.id)?.preparationInstruction||'unrecorded'})),basis:flow.basis,massContext:ctx.massContext(),station:selectedStation,preparation:flow.preparation.method,operationTimeline:flow.operationTimeline,operationalScene:flow.operationalScene,progress,selectedId,liquidRecord:flow.processPlan};
  }
  function massStage() {const mass=ctx.massContext();return `<label class="wb-stage-field">本次克數的稱量階段<select id="mass-stage" aria-label="克數稱量階段">${[['unrecorded','稱量階段未錄'],['processed_dry','炮製後乾飲片・投入前'],['raw_dry','炮製前乾原料'],['other','其他實測材料']].map(([v,t])=>`<option value="${v}" ${mass.stage===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
  function selectionChips() {return ctx.selection().map(r => `<span class="wb-chip">${HerbImages.thumb(r.id,'mini',false)}<button data-detail="${esc(r.id)}">${esc(H(r.id)?.name)}</button><button data-remove="${esc(r.id)}" aria-label="移除${esc(H(r.id)?.name)}">×</button></span>`).join('');}
  function options(r) {return `<option value="source_unspecified" ${r.processingId==='source_unspecified'?'selected':''}>原條目・炮製未選</option>${PROCESSING_DATA.profiles.filter(p=>p.herbIds?.includes(r.id)).map(p=>`<option value="${esc(p.id)}" ${r.processingId===p.id?'selected':''}>${esc(p.label)}</option>`).join('')}<option value="custom_unverified" ${r.processingId==='custom_unverified'?'selected':''}>自訂工藝・藥性未核</option>`;}
  function ratio(r) {return `<div class="ratio-control"><button data-step="-1" data-id="${esc(r.id)}" aria-label="減少${esc(H(r.id)?.name)}研究份數" ${r.ratio<=1?'disabled':''}>−</button><input type="number" min="1" max="20" step="1" value="${r.ratio}" data-ratio="${esc(r.id)}" aria-label="${esc(H(r.id)?.name)}研究份數"><button data-step="1" data-id="${esc(r.id)}" aria-label="增加${esc(H(r.id)?.name)}研究份數" ${r.ratio>=20?'disabled':''}>+</button></div>`;}
  function quantity(flow) {
    const mass = ctx.massContext();
    return `<div class="wb-basis"><label>結構與分析的計量依據<select id="weight-basis" aria-label="標籤分布計量依據"><option value="grams" ${ctx.basis()==='grams'?'selected':''}>實錄克數（g）</option><option value="research" ${ctx.basis()==='research'?'selected':''}>研究份數</option></select></label><p>${ctx.basis()==='grams'?'填入你實際記錄的克數；空白保留未知。':'份數是相對比較權重；可另外記錄克數。'}</p></div>
    ${massStage()}<div class="wb-quantity-list">${ctx.selection().map(r=>`<article class="wb-quantity-row"><div class="wb-material-identity">${HerbImages.thumb(r.id)}<div><button class="material-name" data-detail="${esc(r.id)}">${esc(H(r.id)?.name)}</button><small>${esc(r.sourceAnnotationText || '原方量未載入；不預設克數')}</small><span class="herb-image-label">${HerbImages.label(r.id)}</span></div></div><label class="wb-amount">實錄克數<input type="number" min="0.01" step="0.01" inputmode="decimal" data-grams="${esc(r.id)}" value="${r.grams??''}" placeholder="未錄" aria-label="${esc(H(r.id)?.name)}克數"><span>g</span></label>${ctx.basis()==='research'?`<label>研究份數${ratio(r)}</label>`:''}</article>`).join('')}</div>
    <div class="wb-mass-summary" id="wb-mass-summary">${massSummary(flow)}</div><details class="wb-mass-settings"><summary>批次與克數記錄來源</summary><label>研究批次<input id="mass-batch" value="${esc(mass.batch)}" maxlength="80" aria-label="質量記錄批次"></label><label>克數記錄來源<input id="mass-source" value="${esc(mass.source)}" maxlength="160" aria-label="克數記錄來源"></label></details><p class="rule-note">古籍的兩、錢、枚等保留原文，不換算成克數。克數用來描述組成占比，未建立劑量與藥效關係。</p>`;
  }
  function massSummary(flow) {const m=flow.mass;return `<strong>${m.gramsComplete?fmt(m.totalGrams)+' g':m.knownGrams===null?'克數尚未記錄':fmt(m.knownGrams)+' g · 已錄子集'}</strong><span>${m.recordedCount} / ${m.selectedCount} 味已錄${m.gramsComplete?' · 全方質量可用':' · 全方質量未知'}</span><p>${esc(flow.inputMass.scope)}${flow.inputMass.gramsComplete?' · 投入質量已錄':' · 炮製後全方投入質量待核'}</p>`;}
  function processing(flow) {return flow.workflows.map(w => {
    const r=ctx.selection().find(x=>x.id===w.rowId), node=flow.scene.nodes.find(n=>n.id===w.rowId),pr=profile(r?.processingId), record=r?.processRecord||{};
    return `<article class="wb-process-card"><div class="wb-process-head"><div class="wb-material-identity">${HerbImages.thumb(w.rowId,'mini')}<button class="material-name" data-detail="${esc(w.rowId)}">${esc(H(w.rowId)?.name)}</button></div><span>${r?.grams==null?'克數未錄':fmt(r.grams)+' g'}</span></div><label>選擇炮製分支<select data-processing="${esc(w.rowId)}" aria-label="${esc(H(w.rowId)?.name)}炮製方式">${options(r)}</select></label>${flow.preparation.method==='decoction'?`<label>煎劑投入指令<select data-preparation-instruction="${esc(w.rowId)}" aria-label="${esc(H(w.rowId)?.name)}投入指令">${Object.entries(WorkstationModel.instructionLabels).map(([v,t])=>`<option value="${v}" ${r.preparationInstruction===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<p class="herb-image-label">圖片：${HerbImages.label(w.rowId)} · 所選炮製規格另核</p><p class="wb-source-note">原方註記：${esc(r?.sourceProcessingNote||'未載入；未錄不表示生品')}</p><ol class="wb-process-path">${pr?.workflow?.length?pr.workflow.map(s=>`<li>${esc(s.label)}</li>`).join(''):'<li>來源流程待核</li>'}</ol><p class="wb-process-effect">所選分支性味：${esc(node?.attributes?.nature||'性未錄')} · ${esc(node?.attributes?.flavors?.join('、')||'味未錄')}</p><div class="wb-process-record"><span>${record.stepsNote?esc(record.stepsNote):'尚無研究者工藝實錄'}${record.durationMinutes!=null?' · '+fmt(record.durationMinutes)+' 分鐘':''}${record.temperatureC!=null?' · '+fmt(record.temperatureC)+' °C':''}</span><button class="button secondary" data-process-record="${esc(w.rowId)}">流程與參數</button></div></article>`;
  }).join('') + planFields(flow) + '<p class="rule-note">步驟採來源記載，未載的時間與溫度保留未知。可補實錄；實錄參數不自動變成藥效倍率。</p>';}
  function structure(flow) {return operationList(flow)+`<details class="wb-method-evidence"><summary>組成標註與文獻分析</summary><div class="wb-structure-list">${flow.scene.nodes.map(n=>`<article><button class="material-name" data-detail="${esc(n.id)}">${esc(H(n.id)?.name)}</button><span>${n.weightFraction==null?'占比未知':fmt(n.weightFraction*100)+'%'} · ${esc(n.processingLabel)}</span><label>結構標註<select data-role="${esc(n.id)}" aria-label="${esc(H(n.id)?.name)}結構標註">${['未標註','君','臣','佐','使'].map(r=>`<option ${n.role===r?'selected':''}>${r}</option>`).join('')}</select></label></article>`).join('')}</div><p class="rule-note">君臣佐使由研究者標註；節點連線呈現同方組成。藥材的文獻特性會隨有證據的炮製分支更新。</p><button class="button primary" id="analyze" ${!ctx.selection().length?'disabled':''}>更新文獻輪廓與配伍核對</button><button class="button secondary" data-view="forward">進入全方模型</button><details class="wb-analysis" open><summary>文獻輪廓與來源核對 <span id="analysis-state"></span></summary><div class="analysis-grid"><section><h3>文獻標籤分布</h3><div id="chart-body"></div></section><section><h3>已收錄配伍規則</h3><div id="insight-body"></div></section></div></details><div class="citation-panel" id="formula-citation"></div></details>`;}
  function renderStep(flow) {
    const descriptions=['選取本草，保留原名、炮製註記和來源；目錄對應仍需與實際材料核對。','先選本次稱量的材料狀態，再逐味填寫克數。原料量不自動換成飲片投入量。','核對逐味炮製分支；煎劑另外設定投入指令和製備實錄。','點選工序查看對應操作台；拖曳可旋轉，滾輪可縮放。'];
    $('#wb-step-title').textContent=labels[step];$('#wb-step-description').textContent=descriptions[step];$('#wb-step-number').textContent=`STEP 0${step+1} / 04`;
    const body=$('#wb-editor-body');
    if(step===0)body.innerHTML=`<div class="search-wrap"><input class="search" id="herb-search" placeholder="搜尋藥名、性味或典籍" aria-label="搜尋本草" value="${esc(ctx.query())}"></div><div class="filters" id="catalog-filters">${ctx.filtersHTML()}</div><div class="herb-list" id="herb-list" tabindex="0" aria-label="本草搜尋結果">${ctx.catalogCards()}</div><div class="catalog-foot">${HERB_DATA.herbs.length} 味本草 · 「慎」標記含毒性相關記載</div><h3>已選原料 <span id="wb-selected-count">${ctx.selection().length}</span></h3><div class="wb-selected">${selectionChips()||'<p class="table-note">尚未加入原料</p>'}</div>`;
    else if(!ctx.selection().length)body.innerHTML='<div class="empty-state">先選擇原料，再建立數量與流程記錄。<br><button class="button secondary" data-wb-step="0">返回選原料</button></div>';
    else body.innerHTML=step===1?quantity(flow):step===2?processing(flow):structure(flow);
    $('#wb-prev').disabled=step===0;$('#wb-next').hidden=step===3;$('#wb-next').disabled=!ctx.selection().length;
    $('#wb-next').textContent=(step===1&&flow.steps[1].status==='partial')?'保留未知，設定工序':step===0?'原料已選，實錄稱量':step===1?'確定量，設定工序':'查看操作演示';
    updateNavigation(flow);ctx.renderResults();ctx.renderCitation();
  }
  function updateNavigation(flow) {document.querySelectorAll('[data-wb-step]').forEach(b=>{const i=Number(b.dataset.wbStep);b.classList.toggle('current',i===step);b.setAttribute('aria-current',i===step?'step':'false');const small=b.querySelector('small');if(small)small.textContent=statuses[flow.steps[i].status]});}
  function selectedDetail(flow) {const n=flow.scene.nodes.find(n=>n.id===selectedId);$('#wb-selected-detail').innerHTML=n?`${HerbImages.thumb(n.id)}<strong>${esc(H(n.id)?.name)}</strong><span>${n.grams==null?'克數未錄':fmt(n.grams)+' g'} · ${esc(n.processingLabel)}</span><span class="herb-image-label">${HerbImages.label(n.id)}</span><button class="text-button" data-detail="${esc(n.id)}">藥圖與典籍 ↗</button>`:'<span>點選材料，查看克數、炮製分支與來源。</span>';}
  function updateProgress(value) {progress=value;const range=$('#wb-progress');if(range)range.value=Math.round(value*100);if(!ctx)return;const flow=liveFlow||snapshot(),count=flow.operationTimeline.length,index=Math.min(count-1,Math.floor(value*count)),op=flow.operationTimeline[index];document.querySelectorAll('[data-wb-phase]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.wbPhase)===index?'true':'false'));if(op&&(playing||previewSeeking)){selectedStation=op.stationId;stationDetail(flow);}const label=$('#wb-current-operation');if(label)label.textContent=op?.label||'尚無工序';const status=$('#wb-operation-status');if(status)status.textContent=op?(operationStatuses[op.status]||'待核'):'待錄';}
  function updatePlay(value) {playing=value;const b=$('#wb-play');if(b){b.textContent=value?'Ⅱ 暫停':'▷ 播放流程';b.setAttribute('aria-pressed',String(value));}}
  function originSummary() {const f=ctx.origin();if(!f)return '<span>自選組方 · 質量與結構只涵蓋當前選材。</span>';const skipped=(f.ingredientRefs||[]).filter(r=>!r.id||!ctx.selection().some(s=>s.id===r.id));return `<span><strong>${esc(f.name)} · 原方線索</strong>${skipped.length?'　僅載入已映射子集；未載入：'+esc(skipped.map(r=>r.sourceName||r.name||r.annotationText||'未解析材料').join('、')):'　來源單位保留原文，未預填克數'}。實錄質量只涵蓋當前選材。</span><button class="text-button" data-wb-step="3" data-wb-evidence>查看原方與出處 ↗</button>`;}
  function updateLive() {if(!ctx||!$('#workbench-root'))return;const flow=snapshot();liveFlow=flow;updateOperations(flow);$('#wb-origin').innerHTML=originSummary();$('#wb-live-summary').innerHTML=`<div><strong>${ctx.selection().length}</strong><span>味原料</span></div><div><strong>${flow.mass.gramsComplete?fmt(flow.mass.totalGrams)+' g':flow.mass.knownGrams===null?'量待填':fmt(flow.mass.knownGrams)+' g'}</strong><span>${flow.mass.gramsComplete?'全方實錄':flow.mass.knownGrams===null?'尚未記錄':'僅已錄子集'}</span></div><div><strong>${flow.inputMass.gramsComplete?fmt(flow.inputMass.totalGrams)+' g':'投入量待核'}</strong><span>炮製後投入質量</span></div>`;
    const mass=$('#wb-mass-summary');if(mass)mass.innerHTML=massSummary(flow);
    $('#wb-live-warnings').innerHTML=flow.scene.warnings.map(w=>`<p class="wb-warning">${esc(w.type==='compatibility'?`${H(w.a)?.name} × ${H(w.b)?.name} · 文獻配伍警示`:`${H(w.herbId)?.name} · 毒性與身份核對`)}<button class="text-button" data-detail="${esc(w.herbId||w.a)}">查看藥材</button></p>`).join('');
    const next=$('#wb-next');if(next&&step<3){next.textContent=step===0?'原料已選，實錄稱量':step===1?(flow.steps[1].status==='partial'?'保留未知，設定工序':'確定量，設定工序'):'查看操作演示';}updateNavigation(flow);selectedDetail(flow);if(scene)scene.update(sceneSnapshot(flow));
  }
  function render(context) {
    ctx=context;ProcessingUI.bindContext(ctx);
    if(!$('#workbench-root')){
      dispose();ctx=context;const token=++generation;
      $('#view-content').innerHTML=`<section class="wb-workbench" id="workbench-root"><div class="wb-top"><label>研究名稱<input id="formula-name" value="${esc(ctx.name())}" maxlength="60" aria-label="研究名稱"></label><label>從已錄方子開始<select id="template" aria-label="載入經典方劑"><option value="">載入經典方劑</option>${HERB_DATA.formulas.map(f=>`<option value="${esc(f.id)}" ${ctx.loadedFormulaId()===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label>製備方式<select id="wb-preparation" aria-label="製備方式">${Object.entries(methods).map(([v,t])=>`<option value="${v}" ${ctx.preparation()===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="wb-origin" id="wb-origin"></div><nav class="wb-steps" aria-label="配伍操作步驟">${labels.map((label,i)=>`<button data-wb-step="${i}"><span>0${i+1}</span><b>${label}</b><small></small></button>`).join('')}</nav><div class="wb-layout"><section class="wb-editor"><div class="wb-step-heading"><span class="eyebrow" id="wb-step-number"></span><h2 id="wb-step-title" tabindex="-1"></h2><p id="wb-step-description"></p><button class="text-button wb-scene-jump" data-wb-jump>查看 3D 操作台 ↓</button></div><div class="wb-editor-body" id="wb-editor-body"></div><div class="wb-next-bar"><button class="button secondary" id="wb-prev">上一步</button><button class="button primary" id="wb-next"></button></div></section><aside class="wb-preview"><div class="wb-preview-head"><div><span class="eyebrow">PROCESS WORKSTATIONS</span><h2>材料 → 工序 → 操作台</h2></div><span class="wb-live-indicator">工序示意</span></div><nav class="wb-stations" aria-label="選擇操作台">${Object.entries(stationLabels).map(([id,label])=>`<button data-wb-station="${id}" aria-pressed="${id===selectedStation}">${label}</button>`).join('')}</nav><div class="wb-playbar"><button id="wb-play" aria-pressed="false">▷ 播放流程</button><button id="wb-camera">重設視角</button></div><div id="workbench-scene"><p class="wb-loading">正在準備 3D 操作台…</p></div><div class="wb-timeline"><label for="wb-progress"><strong id="wb-current-operation"></strong><span id="wb-operation-status"></span></label><input id="wb-progress" type="range" min="0" max="100" step="1" value="${Math.round(progress*100)}" aria-label="流程動畫進度"><details class="wb-operation-menu"><summary>選擇工序</summary><div class="wb-phases" id="wb-operation-phases"></div></details><p class="wb-animation-note">播放為工序導覽；分支可平行，秒數不對應實際時間。</p></div><div id="wb-station-detail" class="wb-station-detail"></div><div class="wb-live-summary" id="wb-live-summary"></div><div class="wb-selected-detail" id="wb-selected-detail"></div><div id="wb-live-warnings"></div></aside></div></section>`;
      modulePromise ||= import('./workstation-scene.js?v=ff5f510ef78c');
      modulePromise.then(m=>{if(token!==generation||!$('#workbench-scene'))return;$('#workbench-scene').innerHTML='';scene=m.mountWorkstationScene($('#workbench-scene'),{snapshot:sceneSnapshot(snapshot()),onSelectMaterial:id=>{selectedId=id;selectedDetail(snapshot());},onSelectStation:selectStation,onProgress:updateProgress,onPlayingChange:updatePlay,durationMs:28000});scene.seek(progress);updateLive();}).catch(()=>{if(token===generation&&$('#workbench-scene'))$('#workbench-scene').innerHTML='<p class="wb-loading">3D 暫時無法載入。原料、數量與流程記錄仍可編輯。</p>';});
    }else{$('#formula-name').value=ctx.name();$('#template').value=ctx.loadedFormulaId()||'';$('#wb-preparation').value=ctx.preparation();}
    renderStep(snapshot());updateLive();updateProgress(progress);
  }
  function refresh() {if(ctx&&$('#workbench-root')){renderStep(snapshot());updateLive();}}
  function go(next) {if(!ctx.validateInputs())return;previewSeeking=false;step=Math.max(0,Math.min(3,next));selectedStation=['materials','weighing','processing','assembly'][step];renderStep(snapshot());updateLive();$('#wb-step-title').focus({preventScroll:true});}
  function dispose() {generation++;if(scene)scene.dispose();scene=null;playing=false;}
  function reset() {selectedStation='materials';timelineKey='';step=0;selectedId=null;progress=0;dispose();}
  function planFields(flow) {
    const plan=ctx.processPlan();
    const fields=[['waterMl','本次加水實錄','mL',0.01],['soakMinutes','浸泡實錄','分鐘',0],['firstMinutes','第一煎整段實錄','分鐘',0],['secondMinutes','二煎實錄（有記錄才列工序）','分鐘',0],['temperatureC','實測溫度','°C',null],['filtrateMl','濾液實錄','mL',0.01]];
    return `<section class="wb-plan"><h3>${flow.preparation.method==='decoction'?'製備實錄':'製法與批次記錄'}</h3><p>參數留空表示未錄；投入指令是研究者選擇，需核對原方及操作記錄。</p><div class="wb-plan-grid"><label>研究批次<input data-wb-plan="batch" value="${esc(plan.batch)}" maxlength="80" aria-label="製備研究批次"></label><label>器具記錄<input data-wb-plan="vessel" value="${esc(plan.vessel)}" maxlength="120" placeholder="未錄" aria-label="製備器具記錄"></label>${flow.preparation.method==='decoction'?fields.map(([key,label,unit,min])=>`<label>${label}（${unit}）<input type="number" step="any" ${min===null?'':`min="${min}"`} data-wb-plan="${key}" value="${plan[key]??''}" placeholder="未錄" aria-label="${label}"></label>`).join(''):''}<label class="wb-plan-notes">製法、分支條件與實錄備註<textarea data-wb-plan="notes" rows="3" maxlength="4000" aria-label="製備實錄備註" placeholder="記錄來源分支、先煎／後下等條件或待核事項">${esc(plan.notes)}</textarea></label></div><p class="rule-note">水量只作整段實錄；各容器分配與特殊分支條件未另錄。原料身份、製法和實際執行另需核對。</p></section>${evidence(flow)}`;
  }
  function evidence(flow) {
    return `<details class="wb-method-evidence"><summary>原方製法線索與流程依據</summary>${flow.sourceContext.preparationTexts.length?flow.sourceContext.preparationTexts.map(p=>`<blockquote>${esc(p.text)}</blockquote>`).join(''):'<p>目前來源未提供完整製法；不能憑方名決定製備方式。</p>'}<p>調劑、炮製和製備分別記錄；特殊煎法逐味分流。操作台配置為依據文獻設計的研究介面。</p>${(window.WORKSTATION_SOURCES?.sources||[]).map(src=>`<p><a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.title)} ↗</a></p>`).join('')}<a href="downloads/workstation-sources.json" download>下載流程來源記錄</a></details>`;
  }
  function operationList(flow) {
    return `<section class="wb-operation-list"><h3>${esc(methods[flow.preparation.method])} · 工序導覽</h3><p>點選工序，查看對應器具與材料。欄位已錄只表示記錄程度。</p><ol>${flow.operationTimeline.map((op,i)=>`<li><button data-wb-phase="${i}" aria-pressed="false"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(op.label)}</strong><small>${esc(operationStatuses[op.status]||'待核')}</small></button>${op.equipmentId?`<p>${op.rowIds.length?esc(op.rowIds.map(id=>H(id)?.name||id).join('、')):'器具／整段記錄'} · ${esc(stationLabels[op.stationId])}</p>`:''}</li>`).join('')}</ol></section>`;
  }
  function updateOperations(flow) {
    const key=JSON.stringify(flow.operationTimeline.map(op=>[op.id,op.label,op.status,op.rowIds]));
    const list=$('#wb-operation-phases');if(list&&key!==timelineKey){list.innerHTML=flow.operationTimeline.map((op,i)=>`<button data-wb-phase="${i}" aria-pressed="false">${String(i+1).padStart(2,'0')} · ${esc(op.label)}</button>`).join('');timelineKey=key;}
    stationDetail(flow);
    updateProgress(progress);
  }
  function stationDetail(flow) {
    document.querySelectorAll('[data-wb-station]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.wbStation===selectedStation)));
    const station=flow.stations.find(x=>x.id===selectedStation),detail=$('#wb-station-detail');
    if(detail&&station){const ops=flow.operationTimeline.filter(x=>x.stationId===selectedStation);detail.innerHTML=`<strong>${esc(station.label)}</strong><span>${esc(operationStatuses[station.status]||'待核')} · 未確認實際完成</span><p>${station.note?esc(station.note):selectedStation==='weighing'?esc(flow.inputMass.scope):ops.length?esc(ops.map(o=>o.label).join(' → ')):'此製備方式未啟用'}</p>`;}
  }
  function selectStation(id) {if(!Object.hasOwn(stationLabels,id))return;selectedStation=id;if(scene){scene.setPlaying(false);const flow=snapshot(),index=flow.operationTimeline.findIndex(op=>op.stationId===id);if(index>=0){previewSeeking=true;scene.seek((index+.05)/flow.operationTimeline.length);}scene.focusStation(id);}updateOperations(snapshot());}
  function validatePlanInputs() {for(const el of document.querySelectorAll('[data-wb-plan]'))if(!el.checkValidity()){el.reportValidity();ctx?.notify('請核對製備實錄；水量須大於 0，時間須為 0 或正數');return false;}return true;}
  document.addEventListener('change',e=>{const el=e.target;if(!$('#workbench-root'))return;if(el.id==='wb-preparation'){if(!ctx.validateInputs()){el.value=ctx.preparation();return;}ctx.setPreparation(el.value);}if(el.dataset.preparationInstruction){if(!ctx.validateInputs()){el.value=ctx.selection().find(r=>r.id===el.dataset.preparationInstruction)?.preparationInstruction||'unrecorded';return;}ctx.updateRow(el.dataset.preparationInstruction,{preparationInstruction:el.value});}});
  document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.wbPlan||!ctx)return;const key=el.dataset.wbPlan;if(el.type==='number'){const value=el.value===''?null:Number(el.value);if(el.validity.badInput||value!==null&&(!Number.isFinite(value)||!el.checkValidity())){ctx.updatePlan({[key]:null});return;}ctx.updatePlan({[key]:value});}else ctx.updatePlan({[key]:el.value});});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!$('#workbench-root'))return;if(b.dataset.wbStep!==undefined)go(Number(b.dataset.wbStep));if(b.hasAttribute('data-wb-evidence')){const details=$('#wb-editor-body>.wb-method-evidence');if(details){details.open=true;$('#formula-citation')?.scrollIntoView({behavior:'smooth',block:'center'});}}if(b.hasAttribute('data-wb-jump'))$('.wb-preview')?.scrollIntoView({behavior:'auto',block:'start'});if(b.id==='wb-prev')go(step-1);if(b.id==='wb-next')go(step+1);if(b.id==='wb-play'&&scene){if(progress>=.995&&!playing){progress=0;scene.seek(0);}scene.setPlaying(!playing);}if(b.id==='wb-camera'&&scene)scene.resetCamera();if(b.dataset.wbStation)selectStation(b.dataset.wbStation);if(b.dataset.wbPhase!==undefined&&scene){scene.setPlaying(false);const flow=snapshot(),op=flow.operationTimeline[Number(b.dataset.wbPhase)];if(op){previewSeeking=true;selectedStation=op.stationId;scene.seek((Number(b.dataset.wbPhase)+.05)/flow.operationTimeline.length);scene.focusStation(selectedStation);updateOperations(flow);}}});
  document.addEventListener('input',e=>{if(e.target.id==='wb-progress'&&scene){previewSeeking=true;scene.setPlaying(false);scene.seek(Number(e.target.value)/100);}});
  window.addEventListener('pagehide',dispose);
  return {render,refresh,updateLive,dispose,reset,validatePlanInputs};
})();
